SELECT * FROM (SELECT sub0.time AS "time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", first("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > (time_bucket('1h', '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') AT TIME ZONE 'Europe/Berlin' - interval '1h') AT TIME ZONE 'Europe/Berlin' AND "time" < '2026-01-08T00:00:00Z' GROUP BY 1 ORDER BY 1 ASC) sub0) d WHERE "time" >= time_bucket('1h', '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') ORDER BY 1 DESC